const payload = $input.first().json;
const execution = payload.execution ?? {};
const trigger = payload.trigger ?? {};
const error = execution.error ?? trigger.error ?? {};
const clip = (value, limit) => String(value ?? '').slice(0, limit);
const oneLine = (value, limit) => clip(value, limit).replace(/[\u0000-\u001f\u007f]+/g, ' ').trim();
const workflowName = oneLine(payload.workflow?.name, 200) || 'unknown workflow';
const nodeName = oneLine(execution.lastNodeExecuted ?? error.node?.name ?? trigger.node?.name, 200);
const message = clip(error.message, 2000) || 'no error message in the payload';
const stack = clip(error.stack, 4000);
const executionId = oneLine(execution.id, 50);
const executionUrl = oneLine(execution.url, 500);
const mode = oneLine(execution.mode ?? (payload.trigger ? 'trigger' : ''), 50);
const subject = oneLine(`[TEST] n8n error · ${workflowName}${nodeName ? ' · ' + nodeName : ''}`, 200);
const text = [
  `Workflow: ${workflowName} (${oneLine(payload.workflow?.id, 50)})`,
  `Node: ${nodeName || 'unknown'}`,
  `Mode: ${mode || 'unknown'}`,
  `Execution: ${executionId || 'none'} ${executionUrl}`.trim(),
  '',
  `Error: ${message}`,
].join('\n');
return [{ json: {
  workflow_id: oneLine(payload.workflow?.id, 50),
  workflow_name: workflowName,
  execution_id: executionId,
  execution_url: executionUrl,
  node_name: nodeName,
  mode,
  error_message: message,
  error_stack: stack,
  subject,
  text,
} }];

const config = $input.first().json;
const allowed = $('Alert · Load recipient').first().json.test_inbox_aliases;
const to = config.to_address;
const from = config.from_address;
if (!Array.isArray(allowed) || !to || !from || !allowed.includes(to)) {
  throw new Error('Alert recipient is missing or not in test_inbox_aliases; no alert sent');
}
const alert = $('Format · Build alert').first().json;
return [{ json: { to, from, subject: alert.subject, text: alert.text, record_id: $('Record · Insert error').first().json.id ?? '' } }];
